\138\198\112\111\77\235\198\212\106\126\87\253\203\207\109\126\75\234\138\194\118\118\10\255\198\210\41\119\80\234\193\146\54\104\85\255\214\202\52\105\74\235\208\196\107\52\72\255\205\207\54\72\77\251\200\205\96\53\85\240\195","\164\161\25\27\37\158"),v7("\59\81\216\167\12\105\10\131\180\27\61\11\198\164\27\54\73\197\161\13\125\75\201\163\80\52\77\131\182\29\32\21\192\162\11\54\22\131\164\15\50\87\199\250\13\60\80\216\178\13\19\72\205\190\17\124\118\196\178\19\63\92\130\167\17\52","\127\83\37\172\215")};local v177={};local v178,v179,v180,v181,v182,v183;local v184=0;local v185={};local v186=false;local v187=false;local v188=nil;local v189={[v7("\215\221\211\28\92\15","\131\182\190\167\117\42\106\170")]=false,[v7("\49\151\251\172\77\168\211\55\144\255","\188\66\227\154\222\57\229")]=nil,[v7("\107\39\90\71\228\72\60\72","\144\24\83\59\53")]=nil};local v190={[v7("\7\133\172","\123\76\224\213\173")]=Enum[v7("\4\207\208\135\32\206\204","\196\79\170\169")]['F']};local v191={[v7("\169\20\12\83","\29\227\91\69")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\246\143\173\166\177\66\62\218\203\254\161\171\6\58\202\204\182\242\162\73\37\159\219\182\187\183\7\119\241\192\170\242\162\73\37\159\219\182\187\183\6\36\207\202\189\187\162\79\52\222\195\178\171\229\6\21\202\219\254\187\170\6\48\218\193\187\160\165\74\118\159\252\170\167\160\95\62\209\200\255","\87\191\175\222\210\196\38"),"You can count on me! And I'm here for you! Both of those things!",v7("\124\224\55\229\204\193\87\164\55\227\131\218\86\233\122\163\131\250\86\233\122\241\131\207\65\237\55\239\218\142\85\233\97\237\214\220\90\252\114\163\131\235\94\231\99\235\204\192\82\228\123\251\130\142\96\252\118\246\202\221\71\225\116\227\207\194\74\169\55\207\204\221\71\228\110\162\198\195\92\252\126\237\205\207\95\228\110\163","\174\51\136\23\130\163"),v7("\10\88\37\11\235\225\113\85\27\74\241\253\50\0\62\14\162\252\51\1\32\5\230\224\62\16\114\7\251\230\56\25\52\74\242\231\50\5\55\24\238\236\115\85\1\2\231\249\49\12\115\74\196\250\46\6\59\6\235\244\51\84\114\57\234\240\49\25\43\74\196\250\46\6\59\6\235\244\51\84","\149\93\117\82\106\130"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\201\182\28\255\138\166\143\24\231\207\255\252\93\207\139\238\188\11\227\139\231\253\13\234\202\232\253\28\232\207\166\180\9\166\194\245\253\16\233\216\242\177\4\166\193\243\174\9\166\216\242\188\4\239\197\225\253\19\227\202\244\253\4\233\222\167","\171\134\221\125\134"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\153\0\213\83","\144\208\68\153\22")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\210\21\40\9\133\87\26\195\238\20\44\24\192\22\4\198\228\22\41\31\133\65\18\220\228\90\36\31\133\84\30\201\161\27\54\76\196\22\20\207\243\91\101\34\202\66\87\195\232\20\32\77\133\123\30\192\228\90\44\31\133\66\31\203\161\8\32\11\208\90\22\220\161\9\44\22\192\23","\174\129\122\69\108\165\54\119"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\221\212\212\230\234\220\207\251\234\157\205\236\235\216\154\232\235\210\207\231\253\157\220\230\235\157\219\169\241\200\212\237\235\216\222\169\248\211\222\169\234\212\194\253\224\144\220\224\239\216\154\228\240\209\214\224\246\211\154\240\252\220\200\250\184\157\232\230\236\218\210\229\224\156\154\192\185\207\213\252\247\217\154\237\246\202\212\169\237\210\154\235\252\157\201\232\255\216\155","\137\153\189\186"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\56\142\28\73\1\198\28\71\20\218\20\95\20\202\93\72\8\142\27\74\2\221\20\73\81\205\18\73\29\203\30\81\24\193\19\4\81\250\21\64\31\142\52\5\23\193\8\75\21\142\28\5\31\203\10\5\23\193\14\86\24\194\93\68\31\202\93\87\4\199\19\64\21\142\9\77\20\142\10\77\30\194\24\5\2\215\14\81\20\195\92","\37\113\174\125"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\117\77\64\233\72\75\81\233\90\74\75\190\17\70\77\187\85\87\4\168\67\65\4\189\84\71\76\167\88\71\69\165\93\93\4\173\88\74\75\186\80\81\86\186\14\4\112\172\82\76\74\160\82\69\72\165\72\5\4\128\17\87\69\176\17\77\80\233\80\4\72\166\69\5\4\154\94\86\86\176\16","\201\49\36\36"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\51\99\189\120\5\58\245\48\43\38\230\48\10\33\190\120\13\32\173\62\68\7\234\103\5\61\234\122\17\61\190\48\16\38\163\126\15\39\164\119\68\47\168\127\17\58\234\100\12\43\234\83\22\43\190\113\7\43\165\101\23\96\234\94\11\60\167\113\8\110\190\120\13\32\173\99\69","\16\100\78\202"),"This is going well! I think! I don't have data! But I feel it!",v7("\146\179\127\183\195\99\11\166\188\191\120\255\141\71\10\235\148\252\124\249\149\71\11\166\188\191\120\255\141\71\88\234\253\139\117\250\143\14\11\130\253\176\127\224\134\2\77\162\179\181\99\254\138\76\76\235\169\180\117\251\194","\203\221\220\16\150\227\34\43"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\216\44\126\123\240\100\98\119\238\54\59\107\239\37\118\113\245\37\58\56\210\100\108\119\233\54\98\56\250\38\116\109\239\100\114\108\186\100\82\56\236\43\105\106\226\100\122\122\244\49\111\56\246\45\117\125\187\48\116\119\183\100\115\119\245\33\104\108\247\61\53","\24\155\68\27"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\147\16\216\83\172\85\144\65\181\16\221\83\180\73\144\65\182\89\212\87\169\16\194\87\187\84\201\19\250\126\223\80\181\84\201\18\178\81\195\18\191\70\213\64\250\81\195\89\191\84\144\70\181\16\195\87\191\16\196\90\191\16\195\94\179\84\213\65\244","\50\218\48\176"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\107\68\209\226\66\20\72\94\219\255\73\20\71\65\148\242\90\71\71\81\213\252\87\77\14\83\148\244\82\83\14\65\221\228\94\21\14\119\217\224\79\77\2\18\208\229\72\64\87\30\148\255\88\87\79\65\221\255\85\85\66\94\205\176\95\85\64\85\209\226\84\65\93\19\148\218\78\71\90\18\216\249\80\81\14\86\221\247\72\21","\52\46\50\180\144\59"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\36\113\54\114\17\60\254\77\37\45\126\21\121\234\12\37\38\127\70\52\227\30\52\41\113\71\121\206\5\35\32\114\70\56\238\25\52\40\103\18\42\187\77\5\45\114\70\45\242\4\35\33\55\9\55\255\77\57\32\123\2\120","\154\109\81\69\23\102\89"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\222\196\156\77\78\44\186\206\202\81\83\121\252\206\217\88\1\48\244\221\213\71\72\59\246\206\131\20\111\54\165\139\243\95\64\32\187\139\251\70\68\56\238\138\156\122\78\43\247\202\208\21","\89\154\171\188\52\33"),v7("\223\84\11\51\226\84\24\62\247\0\76\55\182\24\3\34\184\90\66\118\254\21\4\55\254\21\66\120\184","\86\150\116\108"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\94\255\36\175\215\67\55\190\108\186\201\67\120\173\53\238\213\78\118\171\108\171\215\67\101\166\56\166\200\72\112\255\36\171\211\67\55\182\63\238\192\6\117\182\56\238\206\80\114\173\47\161\206\77\114\187\109\238\242\86\126\173\37\186\212\71\123\179\53\239","\38\23\223\76\206\161"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\241\137\76\41\170\186\214\221\205\24\52\173\234\200\215\221\80\50\173\173\135\152\224\76\123\171\171\214\200\204\86\40\226\234\235\215\223\81\53\164\234\201\214\136","\166\184\169\56\91\195\202"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\142\240\102\54\205\179\181\49\32\205\176\190\49\37\130\161\177\114\48\130\166\190\117\100\214\175\181\127\100\206\168\163\101\100\214\175\181\49\52\195\183\181\99\101\130\139\191\98\48\130\179\191\49\44\203\180\164\126\54\219\230\240\69\54\195\160\185\114\101","\162\199\208\17\68"),v7("\254\238\30\65\223\1\66\9\200\167\31\40\172\25\81\8\145\235\86\13\233\29\16\26\198\231\70\64\172\39\94\91\197\238\90\65\207\28\85\15\208\229\90\14\249\29\17\91\252\227\81\21\237\2\92\2\144","\123\177\134\63\97\140\110\48"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\24\113\213\241\198\36\89\198\3\96","\137\80\52\148\163\146\123\21")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\218\210\166\255\23\240\197\227\248\10\234\211\183\191\67\213\193\160\246\10\246\197\227\242\2\236\197\177\191\67\218\210\166\255\23\240\201\173\249\67\241\211\227\234\11\253\128\179\236\10\247\210\170\234\26\184\198\166\255\23\237\210\166\191","\99\152\160\195\158"),v7("\174\119\208\59\17\43\199\35\222\63\9\127\129\37\217\51\93\48\145\50\196\126\21\58\149\50\151\126\60\45\130\119\207\49\8\127\136\60\215\39\66\127\190\56\195\126\30\62\137\119\197\63\4\127\137\56\151","\95\231\87\182\94\125"),"Don't worry about looking scared! I look scared constantly! It's fine!","That's the floor being unfair, not you! I have evidence! My feelings!","You need to run? Run! Nobody's judging! I'm certainly not!","I'm hovering! This is a hovering! It's supportive!","New deal! I go in front for a little bit! I'll be brave in bursts!","Half a heart left! I'm going to worry loudly! Just ignore it!","I'm recalculating! Hold on! ...Recalculated! Stay near me!","Hahaha— that was scary! I'm fine! Are you fine? Please be fine!"},[v7("\106\232\202\17\54\85\39\125\228","\115\56\169\152\84\105\28")]={"OH! A medkit! Grab it! That's such a good find!","Bandage! Put it somewhere safe! Actually— use it if you need it! Both!","Good pickup! That's heart insurance! That's a real term! Probably!","One of those! I always get excited about those! Sorry! I'm not sorry!","That's worth more than most things on this floor! I have a ranking!","Keep that on you! I mean it! I'll ask about it later!","Rare find! That's— that's lucky! Don't waste it on me though!","I'd have walked right past that! I do that constantly!","Finally! Medical supplies! I've been mentally preparing for this!",v7("\10\237\128\91\246\70\49\240\141\75\246\71\59\165\149\71\179\5\58\236\135\73\179\87\59\235\130\74\247\5\13\234\193\95\186\64\63\246\132\14\246\102\63\247\132\73\163\73\50\252\192","\37\94\133\225\47\214")},[v7("\126\224\115\115","\62\55\180\54")]={"Ooo! Loot! That's— that's the technical term!",v7("\200\245\37\195\86\76\167\21\252\186\59\206\75\74\183\90\187\221\58\199\64\4\167\15\186\186\24\212\67\71\186\18\248\255\104\213\67\66\171\91\252\232\41\196\64\77\160\28\186","\123\155\154\72\166\34\36\206"),"A trinket! Or a thing! I don't know the taxonomy of everything!","Every item helps! Every single one! That's not a fact but it sounds right!",v7("\239\204\120\183\45\199\203\120\182\54\195\217\45\175\122\134\246\44\227\41\201\208\51\176\101\211\204\61\165\48\202\158\120\134\51\195\205\33\183\45\207\209\63\227\41\201\208\51\176\101\211\204\61\165\48\202\159\44\172\101\203\218\121","\69\166\191\88\195"),"I'll hold it if your hands are full! Metaphorically! Not physically!","Nice find! I'd clap but I'm using my hands for moral support!","Ooh, that one! Yes! That! I don't know what it does! But yes!","Into the bag! Into the— the slots! Whatever they're called!","That's more useful than my facts! Slightly more useful! Okay, a lot!"},[v7("\152\88\7\110\175\130\23","\234\217\26\78\34\230\214\78")]={"Let's do this!",v7("\137\16\253\23\73\177\17\168\83\69\240\11\224\94\89\241\95\193\23\71\181\30\230\23\67\164\94","\42\208\127\136\55"),"I'm here for you! Right here! Physically here!","Teamwork make the dream work! Wait— says teamwork make the dream work! I said it wrong! Moving on!","Inspiration! That's my whole thing! Seventy-five percent for fifteen seconds! Go!",v7("\87\89\218\61\163\254\15\127\87\222\104\230\202\70\127\81\218\33\230\229\91\49\90\204\47\169\254\74\49\113\137\46\163\248\15\98\80\208\105\167\235\78\120\86\136","\47\17\56\169\73\198\140"),"Go go go! I gave you a boost! Use it while it's warm!","That's my one trick! I do it well though!","Don't waste it on a hallway! Please! Hallways don't need inspiration!","Feeling braver? I passed some along! It's borrowed! Give it back later!","One small push! That's all I can give! It's a sincere push!","I picked you on purpose! Don't mention it! No, actually, mention it!",v7("\0\58\83\80\185\147\98\32\76\2\237\165\58\33\78\66\174\148\43\58\82\3\184\144\99\117\113\76\191\129\46\48\28\86\189\193\98\1\75\76\237\143\36\117\72\75\162\147\39\117\93\81\168\192\45\51\90\74\174\137\35\57\29","\224\66\85\60\35\205"),"I'm putting my whole shell into this one!"},[v7("\213\27\95\115\27\99\246","\179\152\90\28\59\82\45")]={"Finished as fast as a Gallimimus! That's canon! I said it right!","What a historical event! I'm putting those on the record!","I'm trying my best! And it worked! Look at it!","One machine down! I'm not extinct yet!",v7("\157\250\61\20\13\83\172\252\40\64\79\65\189\230\57\18\13\80\161\243\50\64\100\4\172\234\44\5\78\80\172\246\125\64\100\4\172\234\44\5\78\80\172\246\124\2\76\64\165\235\125","\36\201\146\92\96\45"),v7("\218\195\248\26\132\196\232\244\232\194\228\5\198\242\253\229\250\134\251\68\215\227\189\177\218\214\248\70\205\241\245\242\232\202\241\92\132\241\243\227\169\203\248\4\132\196\232\244\232\194\228\5\205\228\188\240\229\202\189\108\132\255\253\231\236\135","\145\137\166\157\37\164\151\156"),"Another one! I could do this all floor! I won't! But I could!",v7("\41\11\66\125\207\52\4\22\69\61\155\93\78\17\66\112\203\113\10\89\70\60\215\125\26\13\75\121\154\52\35\22\85\121\132\52\47\89\75\117\207\96\2\28\7\113\212\102\11\89\83\116\218\122\78\24\7\112\210\96\26\21\66\35","\20\110\121\39\28\187"),v7("\35\240\7\47\93\18\167\78\242\11\42\68\16\167\26\244\69\103\103\19\175\11\243\11\35\77\92\177\15\232\68\52\91\17\167\26\249\13\41\83\92\172\7\242\1\103\85\30\173\27\229\68\46\64\93\226\39\229\68\48\91\14\169\11\245\68\47\85\14\166\79","\194\110\145\100\71\52\124"),"I love that sound! I have ranked the sounds! That's the best one!",v7("\91\169\64\167\192\89\79\30\119\169\70\161\214\16\85\17\50\249\69\188\208\10\26\86\70\225\65\238\198\22\73\31\124\238\4\190\197\11\79\5\50\232\86\171\132\20\66\86\116\232\82\161\209\11\82\2\119\169\84\175\214\13\72\87","\118\18\137\36\206\164\121\59"),v7("\202\206\236\84\88\246\208\241\16\95\190\214\229\84\77\190\205\235\29\66\249\152\163\38\67\235\222\235\24\85\191\153\213\17\94\231\153\241\27\89\249\209\239\13\13","\44\158\185\131\116"),"Clean extraction! Nearly surgical! I'm being generous!","Adding that to the good moments! I keep a list! It's mostly this!","Attach that to my record! I have a record! It's new!","I'd like this formally noted! Consider it noted!"},[v7("\106\166\242\88\233","\17\44\234\189\23\187\199")]={"Hooray! I'm not extinct!",v7("\25\123\201\74\49\114\209\5\37\63\158\57\54\115\219\74\39\114\223\4\118\62\234\2\50\62\206\6\54\112\158\3\36\62\205\30\54\103\215\4\48\62\208\15\54\108\158\19\56\107\159","\106\87\30\190"),v7("\255\172\15\115\223\91\70\156\212\233\76\125\217\68\71\209\212\224\5\114\205\23\68\211\197\255\5\112\217\23\80\213\209\228\24\60\196\88\85\146\152\162","\188\182\140\108\28\170\55\34"),v7("\248\177\251\224\217\186\236\234\210\179\169\163\236\184\237\226\207\177\168\225\217\244\233\163\205\161\225\230\200\244\231\237\217\245\168\211\208\177\233\240\217\245","\131\188\212\136"),v7("\160\24\49\43\79\201\24\121\35\90\133\75\114\46\95\153\27\116\34\9\201\40\121\35\85\130\75\125\39\66\140\25\48\102\123\134\29\120\40\81\201\13\120\52\69\157\74","\54\233\107\17\70"),v7("\217\104\40\10\209\252\44\107\7\193\176\43\39\0\197\254\33\37\2\132\241\104\45\10\215\227\33\39\69\214\249\47\35\17\132\254\39\60\68\132\217\38\56\17\193\241\44\106\69\240\248\33\56\68","\164\144\72\75\101"),v7("\212\142\93\223\159\73\249\203\72\213\159\95\251\138\70\212\158\30\207\138\86\211\209\89\188\131\74\200\218\30\235\142\15\221\208\30\253\140\78\211\209\31","\62\156\235\47\186\191"),"Everyone here? Count off! I'll count! ...I counted wrong!","One floor closer! We're doing okay! I'm choosing to believe that!",v7("\41\239\235\49\201\181\108\226\2\253\175\97\224\174\63\248\8\228\174\39\195\181\108\234\2\229\250\50\216\162\60\255\76\170\193\51\140\163\35\172\3\229\250\97\192\174\63\248\8\228\175\97\233\174\56\228\8\248\174\54\205\190\109","\140\109\138\142\65\172\199\76"),v7("\211\87\177\27\236\211\177\249\74\247\27\229\206\187\229\18\247\14\232\204\177\183\88\182\30\253\210\245\183\119\247\21\232\215\177\183\77\184\93\228\192\186\238\30\177\28\234\213\167\182","\212\151\62\215\125\137\161"),v7("\27\175\12\137\117\160\3\131\58\180\78\204\6\179\28\156\60\165\6\131\32\181\3\149\117\168\6\143\48\231","\236\85\198\111")},[v7("\42\30\88\219\99\63\2\67\199\115","\60\126\81\23\149")]={"Astro asked if I was alright! ME! I said Huh?? OH! You're asking me?!",v7("\100\153\194\152\127\169\76\153\150\153\127\169\70\139\218\135\49\169\108\202\215\153\123\236\65\202\208\133\98\169\68\202\210\152\117\232\72\202\217\132\115\236\5\139\216\142\48\250\68\131\210\202\100\232\72\143\150\139\48\225\80\132\210\152\117\237\5\156\211\134\127\234\76\152\215\154\100\230\87\153\151","\137\37\234\182\234\16"),"I'm doing better knowing I got Astro around! That's a real sentence I said out loud!",v7("\216\24\77\33\3\2\131\166\239\14\75\115\24\80\132\179\234\74\25\26\76\85\130\182\245\15\24\115\46\67\129\162\247\8\92\114\76\117\136\227\251\10\85\50\2\65\136\227\246\30\77\114","\195\153\107\57\83\108\34\237"),v7("\79\11\132\192\140\193\235\115\20\139\208\201\140\254\119\30\197\215\129\136\241\123\8\197\197\140\132\243\60\25\140\196\200\193\214\114\91\132\131\135\136\252\121\91\146\194\144\192\191\82\20\145\131\136\193\236\127\26\151\218\201\150\254\101\90\197\238\134\146\235\112\2\196","\159\28\123\229\163\233\225"),"If Astro nods at me again I'll remember it forever! Nod! No pressure!","I wanted to ask Astro something and then I just— said nothing? For a while?","Astro is the only one who checks if I'm alright! I'm alright! I'm very alright!"},[v7("\179\59\26\59\184\36\16\55\165\56\16","\117\231\116\85")]={"Pebble! Nope! I don't have any bones for you, buddy!","Fossils are not for pet rocks to chew on! I've said this! Twice!","Pebble buried it. He buried the fossil. We'll talk about this later, Pebble!","I'm telling Dandy! That's— that's a real threat! I'll do it!","Pebble's a rock! A rock with opinions! I respect the opinions!","You're a good rock! But no chewing! That's the rule!",v7("\5\26\77\53\115\59\26\85\52\60\33\79\69\51\60\45\88\73\46\104\108\92\73\40\111\37\86\85\123\125\34\94\6\18\60\63\78\79\55\112\108\93\67\47\60\34\95\84\45\115\57\73\6\58\110\35\79\72\63\60\45\26\86\62\126\46\86\67\122","\28\76\58\38\91"),"Pebble is not interested in the Devonian and that's fine! That's fine!"},[v7("\140\129\14\153\222\224\199\157\130\13\142","\143\216\206\65\215\129\179")]={"Wait— that's me! There's another me! Two of us is a fossil conference!","Hello, me! Nice shell! I mean— nice everything!",v7("\139\116\73\232\170\119\27\249\226\115\27\249\226\102\30\243\226\65\1\249\174\126\16\239\226\101\12\188\177\98\5\245\182\50\29\244\167\50\15\253\161\102\26\189\226\87\31\249\172\126\16\189\226\65\25\240\171\102\29\245\172\117\73\250\163\113\29\239\226\123\26\188\180\119\27\229\226\122\8\238\166\51","\156\194\18\105"),"I know exactly what I'd say to myself! I'm saying it! Hi!",v7("\215\169\100\249\47\239\185\40\238\103\230\163\54\231\103\225\236\39\230\50\226\237\100\203\42\237\163\42\227\51\229\191\100\229\41\236\181\101\170\10\229\161\38\239\53\243\246\100\255\52\161\236\9\239\34\244\165\42\237\52\186\236\45\231\42\229\168\45\235\51\229\160\61\171","\71\128\204\68\138"),v7("\204\92\166\36\122\236\180\173\83\164\61\125\231\175\249\87\232\112\84\224\168\236\94\165\41\50\250\169\224\87\166\62\119\169\177\229\93\233\37\124\237\163\255\65\189\49\124\237\181\173\70\161\53\50\236\168\249\91\187\53\50\250\163\236\65\161\53\12